# owner: platform
"""Finding the stretches of opening hours nobody covers."""

from typing import Iterable, List

from hourglass.merging import merge_spans
from hourglass.models import Span
from hourglass.parsing import format_span


def _uncovered(merged: List[Span], opening: Span):
    cursor = opening.start
    for span in merged:
        if span.start > cursor:
            yield Span(cursor, span.start)
        cursor = span.end
    if cursor < opening.end:
        yield Span(cursor, opening.end)


# ---
def find_gaps(worked: Iterable[Span], opening: Span):
    """Labels such as 'gap 12:00-13:00 (60 min)'."""
    merged = merge_spans(worked)
    for span in merged:
        if span.start < opening.start or span.end > opening.end:
            raise ValueError(f"outside opening hours: {span}")
    return [
        f"gap {format_span(gap)} ({gap.minutes} min)"
        for gap in _uncovered(merged, opening)
    ]
EOF
cat > tests/test_gaps.py <<'EOF'
# owner: platform
import unittest

from hourglass.gaps import find_gaps
from hourglass.models import Span

OPEN = Span(540, 1020)


class FindGapsTests(unittest.TestCase):
    def test_gap_between_spans(self):
        worked = [Span(540, 720), Span(780, 1020)]
        self.assertEqual(
            find_gaps(worked, OPEN),
            ["gap 12:00-13:00 (60 min)"]
        )

    def test_edges_and_overlaps(self):
        worked = [Span(600, 700), Span(650, 900)]
        self.assertEqual(
            find_gaps(worked, OPEN),
            [
                "gap 09:00-10:00 (60 min)",
                "gap 15:00-17:00 (120 min)"
            ]
        )

    def test_nothing_worked(self):
        self.assertEqual(
            find_gaps([], OPEN),
            ["gap 09:00-17:00 (480 min)"]
        )

    def test_full_cover(self):
        self.assertEqual(find_gaps([OPEN], OPEN), [])

    def test_outside_opening_hours(self):
        with self.assertRaises(ValueError):
            find_gaps([Span(480, 600)], OPEN)
EOF
